package com.makemytrip.makemytrip.services;
import com.makemytrip.makemytrip.models.*;import com.makemytrip.makemytrip.repositories.*;import org.junit.jupiter.api.Test;import org.junit.jupiter.api.extension.ExtendWith;import org.mockito.InjectMocks;import org.mockito.Mock;import org.mockito.junit.jupiter.MockitoExtension;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;import java.util.Optional;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.ArgumentMatchers.any;import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class) class ReviewServiceTest{@Mock ReviewRepository reviews;@Mock BookingRepository bookings;@Mock ReviewHelpfulVoteRepository votes;@Mock org.springframework.data.mongodb.core.MongoTemplate mongo;@InjectMocks ReviewService service;private Booking booking(){Booking b=new Booking();b.setId("b1");b.setUserId("u1");b.setBookingType(Booking.Type.FLIGHT);b.setFlightId("f1");b.setStatus(Booking.Status.COMPLETED);return b;}private Review review(){Review r=new Review();r.setBookingId("b1");r.setTargetType(Review.TargetType.FLIGHT);r.setTargetId("f1");r.setRating(5);r.setText("Good");return r;}
 @Test void createsPendingReviewForCompletedOwnedBooking(){when(bookings.findById("b1")).thenReturn(Optional.of(booking()));when(reviews.existsByUserIdAndBookingId("u1","b1")).thenReturn(false);when(reviews.save(any())).thenAnswer(x->x.getArgument(0));Review r=service.create(review(),"u1");assertEquals(Review.Status.PENDING,r.getStatus());assertEquals("u1",r.getUserId());}
 @Test void rejectsRatingOutsideRange(){Review r=review();r.setRating(6);ResponseStatusException e=assertThrows(ResponseStatusException.class,()->service.create(r,"u1"));assertEquals(HttpStatus.BAD_REQUEST,e.getStatusCode());verifyNoInteractions(bookings);}
 @Test void rejectsReviewForAnotherUsersBooking(){when(bookings.findById("b1")).thenReturn(Optional.of(booking()));ResponseStatusException e=assertThrows(ResponseStatusException.class,()->service.create(review(),"u2"));assertEquals(HttpStatus.FORBIDDEN,e.getStatusCode());}
 @Test void rejectsReviewOfUncompletedBooking(){Booking b=booking();b.setStatus(Booking.Status.CONFIRMED);when(bookings.findById("b1")).thenReturn(Optional.of(b));ResponseStatusException e=assertThrows(ResponseStatusException.class,()->service.create(review(),"u1"));assertEquals(HttpStatus.CONFLICT,e.getStatusCode());}
 @Test void rejectsDuplicateReviewForBooking(){when(bookings.findById("b1")).thenReturn(Optional.of(booking()));when(reviews.existsByUserIdAndBookingId("u1","b1")).thenReturn(true);ResponseStatusException e=assertThrows(ResponseStatusException.class,()->service.create(review(),"u1"));assertEquals(HttpStatus.CONFLICT,e.getStatusCode());verify(reviews,never()).save(any());}
 @Test void anotherUserCannotEditOrDeleteReview(){Review r=review();r.setUserId("u1");when(reviews.findById("r1")).thenReturn(Optional.of(r));assertEquals(HttpStatus.FORBIDDEN,assertThrows(ResponseStatusException.class,()->service.edit("r1",review(),"u2")).getStatusCode());assertEquals(HttpStatus.FORBIDDEN,assertThrows(ResponseStatusException.class,()->service.delete("r1","u2")).getStatusCode());verify(reviews,never()).delete(any(Review.class));}
 @Test void helpfulVoteCannotBeRepeatedBySameUser(){Review approved=review();approved.setStatus(Review.Status.APPROVED);when(reviews.findById("r1")).thenReturn(Optional.of(approved));when(votes.existsByReviewIdAndUserId("r1","u1")).thenReturn(true);ResponseStatusException e=assertThrows(ResponseStatusException.class,()->service.helpful("r1","u1"));assertEquals(HttpStatus.CONFLICT,e.getStatusCode());verify(votes,never()).save(any());}}
